(5915615, 862334, 15711, '<td valign="top">Thank God, it''s not a drop of water!!! I love the varying degrees of focus on the shards of the pencil lead. :)</td>', 'Thank God, it''s not a drop of water!!! I love the varying degrees of focus on the shards of the pencil lead. :)', '2010-03-24 08:39:46.000000', NULL, 1),
(5915617, 862675, 15711, '<td valign="top">Oh wow, I hadn''t thought of that song in ages.  The abstract use of diagonal line, light and shadow is cool.</td>', 'Oh wow, I hadn''t thought of that song in ages.  The abstract use of diagonal line, light and shadow is cool.', '2010-03-24 08:40:19.000000', NULL, 1),
(5915618, 862336, 15711, '<td valign="top">This looks like something you''d see for an ad in a glossy magazine.</td>', 'This looks like something you''d see for an ad in a glossy magazine.', '2010-03-24 08:41:27.000000', NULL, 1),
(5915619, 862339, 15711, '<td valign="top">This made me smile. I like that their clothing colors work with the sky, so as not to distract one from the other.</td>', 'This made me smile. I like that their clothing colors work with the sky, so as not to distract one from the other.', '2010-03-24 08:41:59.000000', NULL, 1),
(5915622, 862227, 15711, '<td valign="top">Stunning.  I love the contrast The contre jour is beautiful. Well scene and done. :) 9</td>', 'Stunning.  I love the contrast The contre jour is beautiful. Well scene and done. :) 9', '2010-03-24 08:42:50.000000', NULL, 1),
(5915627, 862662, 15711, '<td valign="top">Well done.  The DOF is perfect and they way they almost fill the frame keeps our eyes on them and not anything in the blurred background. I like the overall sense of a diagonal line from lower left to upper right.  Nice going.</td>', 'Well done.  The DOF is perfect and they way they almost fill the frame keeps our eyes on them and not anything in the blurred background. I like the overall sense of a diagonal line from lower left to upper right.  Nice going.', '2010-03-24 08:44:20.000000', NULL, 1),
(5915628, 862440, 15711, '<td valign="top">Love the title.  This is different.  No baseball, no surfers, no water drops.  Thanks for thinking outside of the box.</td>', 'Love the title.  This is different.  No baseball, no surfers, no water drops.  Thanks for thinking outside of the box.', '2010-03-24 08:44:52.000000', NULL, 1),
(5915632, 862599, 15711, '<td valign="top">Anyone who knows me, knows I love this.  I like that the horse in the background is almost the white ones shadow, literally and figuratively. :) 7</td>', 'Anyone who knows me, knows I love this.  I like that the horse in the background is almost the white ones shadow, literally and figuratively. :) 7', '2010-03-24 08:46:22.000000', NULL, 1),
