(5916963, 862634, 40391, '<td valign="top">Good action shot and colours but too small for me. Possibly would have been better without the sand - but you may have cropped more that you had wanted to already.</td>', 'Good action shot and colours but too small for me. Possibly would have been better without the sand - but you may have cropped more that you had wanted to already.', '2010-03-25 06:14:55.000000', NULL, 1),
(5916964, 862265, 40391, '<td valign="top">Did you want grandkids? (assuming this is your kid). Well captured (may have been improved with a shallower DoF in MHO)</td>', 'Did you want grandkids? (assuming this is your kid). Well captured (may have been improved with a shallower DoF in MHO)', '2010-03-25 06:16:54.000000', NULL, 1),
(5916967, 861792, 40391, '<td valign="top">Nice capture but to distant for me.</td>', 'Nice capture but to distant for me.', '2010-03-25 06:21:55.000000', NULL, 1),
(5916968, 862522, 40391, '<td valign="top">Ooops!  Better luck next time.<br/> <br/>Would have been better for me with a different white balance or made a bit warmer.</td>', 'Ooops!  Better luck next time. Would have been better for me with a different white balance or made a bit warmer.', '2010-03-25 06:23:35.000000', NULL, 1),
(5916969, 862475, 40391, '<td valign="top">Did it go in? Well captured, nice contrasts and b&amp;w is a good choice.</td>', 'Did it go in? Well captured, nice contrasts and b&w is a good choice.', '2010-03-25 06:24:30.000000', NULL, 1),
(5916970, 862292, 40391, '<td valign="top">Now this really appeals to me. Great shot!</td>', 'Now this really appeals to me. Great shot!', '2010-03-25 06:25:13.000000', NULL, 1),
(5916972, 862662, 40391, '<td valign="top">You''d have to be happy with this photo. Love the shallow depth of field and colours. Good luck</td>', 'You''d have to be happy with this photo. Love the shallow depth of field and colours. Good luck', '2010-03-25 06:26:14.000000', NULL, 1),
(5916974, 861446, 40391, '<td valign="top">Great capture!</td>', 'Great capture!', '2010-03-25 06:27:10.000000', NULL, 1),
(5916975, 862297, 40391, '<td valign="top">I love the spiderman in the reflection! Well done!</td>', 'I love the spiderman in the reflection! Well done!', '2010-03-25 06:28:04.000000', NULL, 1),
(5916976, 862569, 40391, '<td valign="top">Very good emotional shot but a bit too much movement for this challenge to do very well IMHO.</td>', 'Very good emotional shot but a bit too much movement for this challenge to do very well IMHO.', '2010-03-25 06:28:52.000000', NULL, 1),
(5916979, 862442, 40391, '<td valign="top">Sharp callouses? (sorry for spelling) Nice capture. Evern with the movement of water I still feel it is ''stopped'' enough for me. Well done. 8</td>', 'Sharp callouses? (sorry for spelling) Nice capture. Evern with the movement of water I still feel it is ''stopped'' enough for me. Well done. 8', '2010-03-25 06:31:06.000000', NULL, 1),
(5916981, 862643, 40391, '<td valign="top">Wow! What can I say - brilliant!! 9</td>', 'Wow! What can I say - brilliant!! 9', '2010-03-25 06:32:34.000000', NULL, 1),
(5916982, 862287, 5364, '<td valign="top">It''s a marvellous capture, but I really don''t see what the fat border is adding to the overall image</td>', 'It''s a marvellous capture, but I really don''t see what the fat border is adding to the overall image', '2010-03-25 06:32:54.000000', NULL, 1),
(5916983, 861891, 40391, '<td valign="top">Fantasic photo and colours. 9</td>', 'Fantasic photo and colours. 9', '2010-03-25 06:33:40.000000', NULL, 1),
(5916984, 862516, 5364, '<td valign="top">It''s a great capture, but I find that border is intrusive to the point of overwhelming your subject</td>', 'It''s a great capture, but I find that border is intrusive to the point of overwhelming your subject', '2010-03-25 06:34:25.000000', NULL, 1),
(5916985, 862334, 40391, '<td valign="top">This is a fantastic capture! I guess we can see something similar in Orange? 9 from me.</td>', 'This is a fantastic capture! I guess we can see something similar in Orange? 9 from me.', '2010-03-25 06:35:09.000000', NULL, 1),
(5916986, 862021, 40391, '<td valign="top">I see this almost every morning in the Royal National Park. But I don''t think I could ever capture it as well as you. Great shot! 9</td>', 'I see this almost every morning in the Royal National Park. But I don''t think I could ever capture it as well as you. Great shot! 9', '2010-03-25 06:36:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5916988, 862162, 40391, '<td valign="top">Now this is a different way to capture water - love the colours, setting and concept. Well done!</td>', 'Now this is a different way to capture water - love the colours, setting and concept. Well done!', '2010-03-25 06:36:42.000000', NULL, 1),
(5916989, 861886, 5364, '<td valign="top">Normally I wouldn''t like this kind of processing, but here I feel it really fits the subject.</td>', 'Normally I wouldn''t like this kind of processing, but here I feel it really fits the subject.', '2010-03-25 06:36:45.000000', NULL, 1),
(5916990, 862622, 40391, '<td valign="top">Great timing and capture!I love the reflection and the use of B&amp;W. Only critism would be the slight blur of the wing which is a little against the spirit of the challenge and may cost you some points.  That said, it meets the requirements enough from me and it''s such a great photo that I can''t help but give this a 9. Well done</td>', 'Great timing and capture!I love the reflection and the use of B&W. Only critism would be the slight blur of the wing which is a little against the spirit of the challenge and may cost you some points.  That said, it meets the requirements enough from me and it''s such a great photo that I can''t help but give this a 9. Well done', '2010-03-25 06:36:50.000000', NULL, 1),
(5916991, 862536, 40391, '<td valign="top">Great capture &amp; DoF. Well done! 9 from me.</td>', 'Great capture & DoF. Well done! 9 from me.', '2010-03-25 06:36:54.000000', NULL, 1),
(5916994, 862452, 40391, '<td valign="top">As expected there''s a few droplets in this challenge.  However, the colours and perfect capture of the rebound drop (if that''s the right term) makes it very special. A 9 and favourite from me (and I don''t have many favourites).<br/> <br/>After viewing all the photo''s and re-looking at the one''s that I really like I realise that this has been one of the best challenges I''ve seen in some time. I don''t usually change scores from my original vote but yours is a rare exception. This will be my only 10 for the challenge as I believe the shot is near perfect IMHO. If this dosn''t get a ribbon it''s probably due to a biased opion of water in this type of challenge by some. In this case I believe it would amount to a misscarage of justice. You must be so proud of this shot. Cheers.</td>', 'As expected there''s a few droplets in this challenge.  However, the colours and perfect capture of the rebound drop (if that''s the right term) makes it very special. A 9 and favourite from me (and I don''t have many favourites). After viewing all the photo''s and re-looking at the one''s that I really like I realise that this has been one of the best challenges I''ve seen in some time. I don''t usually change scores from my original vote but yours is a rare exception. This will be my only 10 for the challenge as I believe the shot is near perfect IMHO. If this dosn''t get a ribbon it''s probably due to a biased opion of water in this type of challenge by some. In this case I believe it would amount to a misscarage of justice. You must be so proud of this shot. Cheers.', '2010-03-25 06:44:34.000000', NULL, 1),
(5917002, 862662, 113419, '<td valign="top">look at the emotion!  Great Capture!!!</td>', 'look at the emotion!  Great Capture!!!', '2010-03-25 07:08:46.000000', NULL, 1),
(5917003, 862296, 113419, '<td valign="top">looking at the south end of north bound cattle....I believe I woulda cropped out the one there standing still</td>', 'looking at the south end of north bound cattle....I believe I woulda cropped out the one there standing still', '2010-03-25 07:10:03.000000', NULL, 1),
(5917004, 862643, 113419, '<td valign="top">WOW AMAZING CAPUTRE!</td>', 'WOW AMAZING CAPUTRE!', '2010-03-25 07:10:27.000000', NULL, 1),
