(6037542, 862334, 114969, '<td valign="top">Thank you!<br/>I used a "StopShot" module from "Cognisys". It was connected to a cheap mono microphone (sound quality wasn''t important here ;))</td>', 'Thank you!I used a "StopShot" module from "Cognisys". It was connected to a cheap mono microphone (sound quality wasn''t important here ;))', '2010-06-02 13:02:48.000000', NULL, 0),
(6080006, 862538, 100393, '<td valign="top">Beauty of image: Low<br/>Technical skill: Low<br/> <br/>The block of black in the centre is problematical but the background really kills it. Great concept though.</td>', 'Beauty of image: LowTechnical skill: Low The block of black in the centre is problematical but the background really kills it. Great concept though.', '2010-07-04 20:16:54.000000', NULL, 0),
(6098314, 862533, 46918, '<td valign="top">Interesting looking bird. Not the pretties bird around but I like it. The colors look a little blown. The sky was not helping you out at all. Overall decent shot.<br/> <br/><a href="//www.dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=1014133&amp;page=3#6097977" rel="nofollow" target="_blank">{Game: Comment or Die}</a></td>', 'Interesting looking bird. Not the pretties bird around but I like it. The colors look a little blown. The sky was not helping you out at all. Overall decent shot. {Game: Comment or Die}', '2010-07-20 16:23:03.000000', NULL, 0),
